// REGENERATING
//
// Needed if the backend's certificate authority ever changes (a Render
// platform change, or moving the backend behind a different provider). The
// symptom is every ball failing to send while Wi-Fi is fine, with the serial
// log showing HTTPS failures right after 'Time synced'.
//
// Find the root the host actually chains to:
//   openssl s_client -connect <backend-host>:443 -servername <backend-host>
//
// Download that root from the CA's own site, then PROVE it validates the live
// host before flashing it to anything:
//   openssl s_client -connect <backend-host>:443 -servername <backend-host> \
//     -CAfile <root>.pem -verify_return_error
// Expect: 'Verify return code: 0 (ok)'.
//
// Then paste the PEM into the bundle above. Roots are long-lived (the ones
// here run to 2035/2036), so this should be rare -- but a ball that cannot
// validate will buffer its kicks rather than send them insecurely, which is
// the intended failure mode.

#endif
